{"path": "frontend/src/style.css", "content": "* {
  box-sizing: border-box;
}

body {
  font-family: sans-serif;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  height: 100vh;
}

#app {
  display: flex;
  flex-direction: column;
  height: 100%;
}

header {
  display: flex;
  align-items: center;
  padding: 10px;
  background: #f0f0f0;
  border-bottom: 1px solid #ccc;
}

header button {
  margin-right: 10px;
  padding: 5px 10px;
}

header h2 {
  margin: 0 0 0 20px;
  font-size: 1.2rem;
}

.calendar-container {
  display: flex;
  flex: 1;
  overflow-y: auto;
  position: relative;
}

.time-axis {
  width: 60px;
  flex-shrink: 0;
  position: relative;
  border-right: 1px solid #ccc;
  background: #fafafa;
}

.time-label {
  position: absolute;
  right: 5px;
  font-size: 12px;
  color: #666;
  transform: translateY(-50%);
}

.week-grid {
  display: flex;
  flex: 1;
  position: relative;
}

.day-column {
