  loadWeek();
});

document.getElementById('next-week').addEventListener('click', () => {
  currentWeekStart = addDays(currentWeekStart, 7);
  loadWeek();
});

document.getElementById('today').addEventListener('click', () => {
  currentWeekStart = getMonday(new Date());
  loadWeek();
});

initGrid();
loadWeek();
